-- ============================================================
-- Osman Bey 1299 Scenario - city-states of 1299
-- Removes the base-game city-states that did not exist in 1299
-- (or have no place on this map) and adds the beyliks and
-- kingdoms of the time. Generated by tools/build_mod.py.
-- ============================================================
CREATE TABLE OB_KeepMinors (Type TEXT);
DELETE FROM MinorCivilization_CityNames WHERE MinorCivType NOT IN (SELECT Type FROM OB_KeepMinors);
DELETE FROM MinorCivilization_Flavors WHERE MinorCivType NOT IN (SELECT Type FROM OB_KeepMinors);
DELETE FROM MinorCivilizations WHERE Type NOT IN (SELECT Type FROM OB_KeepMinors);
DROP TABLE OB_KeepMinors;


